/* v17：三段式流程 — 姓名 → 介绍 → 模拟 */
(function bindIntakeFlow(){
  const nameInput = el('learnerNameInput');
  const hint = el('learnerNameHint');
  const introTag = el('introLearnerTag');

  // 预填上次的姓名
  try{
    const saved = safeStorage.getItem('co-v17-learnerName') || '';
    if(saved && nameInput){ nameInput.value = saved; }
  }catch(_){}

  function currentName(){ return (nameInput && nameInput.value || '').trim(); }

  // 回车键 = 下一步
  if(nameInput){
    nameInput.addEventListener('keydown', (e)=>{
      if(e.key === 'Enter'){ e.preventDefault(); el('toIntroBtn').click(); }
    });
    nameInput.addEventListener('input', ()=>{
      if(hint){ hint.classList.remove('error'); hint.textContent = '姓名仅保存在本地。'; }
      nameInput.classList.remove('error');
    });
  }

  // 回流用户：若已有保存姓名，显示跳过按钮（briefing 模式下隐藏）
  try{
    const savedForSkip = safeStorage.getItem('co-v17-learnerName') || '';
    if(savedForSkip && !window._briefingMode){
      const skipWrap = el('skipIntroWrap');
      if(skipWrap) skipWrap.style.display = 'block';
    }
  }catch(_){}

  el('skipIntroBtn') && el('skipIntroBtn').addEventListener('click', ()=>{
    // In briefing mode: notify parent to handle skip, do NOT enter game
    if(window._briefingMode){
      if(window.parent !== window){
        window.parent.postMessage({ type: 'BRIEFING_SKIP_REQUESTED' }, '*');
      }
      return;
    }
    // Use input value, or fall back to pre-injected state.learnerName (when name block is hidden)
    const name = currentName() || state.learnerName || '';
    if(!name){
      if(hint){ hint.classList.add('error'); hint.textContent = '请输入姓名后继续。'; }
      if(nameInput){ nameInput.classList.add('error'); nameInput.focus(); }
      return;
    }
    state.learnerName = name;
    try{ safeStorage.setItem('co-v17-learnerName', name); }catch(_){}
    revealSimulationChrome();
    showScreen('network');
    render();
  });

  el('toIntroBtn').addEventListener('click', ()=>{
    const name = currentName() || state.learnerName || '';
    if(!name){
      if(hint){ hint.classList.add('error'); hint.textContent = '请输入姓名后继续。'; }
      if(nameInput){ nameInput.classList.add('error'); nameInput.focus(); }
      return;
    }
    state.learnerName = name;
    try{ safeStorage.setItem('co-v17-learnerName', name); }catch(_){}
    if(introTag) introTag.textContent = '' + name;
    if(window._refreshIntroName) window._refreshIntroName();
    // Advance to slide 2 (mission)
    if(window._introGoTo) window._introGoTo(2);
  });

  el('backToNameBtn').addEventListener('click', ()=>{
    // Scroll slide 1 name input into view instead of going to a separate screen
    if(window._introGoTo) window._introGoTo(1);
    setTimeout(()=>{ if(nameInput){ nameInput.focus(); nameInput.scrollIntoView({behavior:'smooth',block:'center'}); } }, 320);
  });
})();

/* v17：startBtn = 「开始模拟」（揭示顶栏/HUD + 进入 task 回顾页） */
el('startBtn').addEventListener('click',()=>{
  // In briefing mode: notify parent to enter game, do NOT enter game here
  if(window._briefingMode){
    if(window.parent !== window){
      window.parent.postMessage({ type: 'BRIEFING_ENTER_GAME' }, '*');
    }
    return;
  }
  // 保障：如果用户直接跳过姓名页（如利用 URL），也尝试读存储
  if(!state.learnerName){
    try{ state.learnerName = safeStorage.getItem('co-v17-learnerName') || ''; }catch(_){}
  }
  revealSimulationChrome();
  showScreen('network');
  render();
});

