function reset(){
  const keepName = state && state.learnerName ? state.learnerName : '';
  state = initState();
  state.learnerName = keepName;
  if(el('predictInput')) el('predictInput').value='';
  updateRoleUI();
  // v17：重玩时保持在模拟内 (task 页)，顶栏/HUD 已显示无需再次显示
  revealSimulationChrome();
  showScreen('network');
  render();
  closeModal();
}

/* v17：从「Name → 介绍 → 模拟」过渡时揭示顶栏/HUD/标签栏 */
function revealSimulationChrome(){
  // Remove the anti-flash early-hide style if it was injected
  if(window._autoStartEarlyHide){
    document.querySelectorAll('style').forEach(function(s){
      if(s.textContent && s.textContent.indexOf('anti-flash') !== -1) s.remove();
    });
    window._autoStartEarlyHide = false;
  }
  // v20: Initial化移动端网络视图
  const netScreen = document.getElementById('screen-network');
  if(netScreen && !netScreen.classList.contains('network-view') && !netScreen.classList.contains('list-view')){
    netScreen.classList.add('network-view');
  }
  const topbarActions = el('topbarActions');
  if(topbarActions) topbarActions.style.display = 'flex';
  const hudBar = el('hudBar');
  if(hudBar) hudBar.style.display = '';
  const tabsBar = el('tabsBar');
  if(tabsBar) tabsBar.style.display = '';
  // Show mobile bottom nav
  const mobileNav = el('mobileBottomNav');
  if(mobileNav) mobileNav.style.display = '';
  const badge = el('learnerBadge');
  if(badge){
    if(state.learnerName){
      badge.textContent = '👤 ' + state.learnerName;
      badge.style.display = '';
    } else {
      badge.style.display = 'none';
    }
  }

  // Signal to parent React shell that game UI is fully ready
  try { window.parent.postMessage({ type: 'GAME_READY' }, '*'); } catch(e){}
}

/* v17：Role UI 更新 (精简为单Role) */
