/* 模态焦点陷阱 + ESC Close */
document.addEventListener('keydown',(e)=>{
  const modal=el('impactModal');
  if(!modal.classList.contains('show')) return;
  if(e.key==='Escape'){ closeModal(); return; }
  if(e.key==='Tab'){
    const focusables = modal.querySelectorAll('button');
    if(!focusables.length) return;
    const first=focusables[0], last=focusables[focusables.length-1];
    if(e.shiftKey && document.activeElement===first){ e.preventDefault(); last.focus(); }
    else if(!e.shiftKey && document.activeElement===last){ e.preventDefault(); first.focus(); }
  }
});

/* =========================================================
   Mobile: swipe left/right to switch screens
   ========================================================= */
(function bindSwipe(){
  const host = el('swipeHost');
  const order = ['task','network','decision','log'];
  let startX=0, startY=0, tracking=false;
  host.addEventListener('touchstart',(e)=>{
    if(window.innerWidth>980) return;
    if(e.touches.length!==1) return;
    if(e.target.closest('svg')) return;
    if(e.target.closest('textarea')) return;  // do not block input fields
    if(e.target.closest('input,select,button,.action,.target,.target-selector')) return; // v17: avoid conflict with action cards
    if(state.currentScreen==='decision') return; // v17: disable swipe on decision page to avoid drag/click conflicts
    tracking=true;
    startX=e.touches[0].clientX;
    startY=e.touches[0].clientY;
  },{passive:true});
  host.addEventListener('touchend',(e)=>{
    if(!tracking) return;
    tracking=false;
    const t=e.changedTouches[0];
    const dx=t.clientX-startX, dy=t.clientY-startY;
    if(Math.abs(dx)<60 || Math.abs(dx)<Math.abs(dy)) return;
    const idx=order.indexOf(state.currentScreen);
    if(dx<0 && idx<order.length-1){ showScreen(order[idx+1]); render(); }
    else if(dx>0 && idx>0){ showScreen(order[idx-1]); render(); }
  });
})();

/* v24：首次加载 — 直接显示 intro 页 (已包含Name输入) */
(function bootstrap(){
  var urlParams = new URLSearchParams(window.location.search);
  var autoStart = urlParams.get('autoStart') === '1';
  var briefingMode = urlParams.get('mode') === 'briefing';
  // Store mode flags for SET_PLAYER handler
  window._briefingMode = briefingMode;
  window._autoStart = autoStart;

  // Always hide the name input block — name comes from the parent app (localStorage)
  var nameBlock = document.getElementById('introNameBlock');
  if(nameBlock) nameBlock.style.display = 'none';

  // Pre-fill name from URL param or localStorage for in-game display
  var prefilledName = urlParams.get('playerName') || '';
  if(!prefilledName){
    try{ prefilledName = localStorage.getItem('co-v17-learnerName') || ''; }catch(_){}
  }
  if(prefilledName){
    var niPre = document.getElementById('learnerNameInput');
    if(niPre) niPre.value = prefilledName;
    state.learnerName = prefilledName;
    try{ localStorage.setItem('co-v17-learnerName', prefilledName); }catch(_){}
    // In briefing mode, hide the skip button (parent shell has its own skip)
    if(!briefingMode){
      var skipWrapPre = document.getElementById('skipIntroWrap');
      if(skipWrapPre) skipWrapPre.style.display = 'flex';
    }
  }

  updateRoleUI();
  // 确保 intro 屏幕激活 (autoStart 模式下跳过，避免闪现)
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  const introEl = el('screen-intro');
  // In autoStart mode: forcibly hide intro BEFORE render() runs, so it never flashes
  if(autoStart && introEl){
    introEl.style.display = 'none';
    introEl.style.visibility = 'hidden';
    introEl.style.opacity = '0';
    introEl.classList.remove('active');
  }
  if(introEl && !autoStart) introEl.classList.add('active');
  // 预填已Save的Name
  if(state.learnerName){
    const ni = el('learnerNameInput');
    if(ni) ni.value = state.learnerName;
    const introTag = el('introLearnerTag');
    if(introTag) introTag.textContent = '' + state.learnerName;
    // 显示跳过按钮 (briefing 模式下隐藏，由父页面的按钮处理)
    if(!window._briefingMode){
      const skipWrap = el('skipIntroWrap');
      if(skipWrap) skipWrap.style.display = 'flex';
    }
    if(window._refreshIntroName) window._refreshIntroName();
  }
  // 渲染 (不可见也没Relationships，以便进入模拟后直接可用)
  render();
  closeModal();
  // If ?autoStart=1, skip intro immediately (game mode — no flash)
  if(autoStart){
    try{
      // Read name from URL param ?name=... or from localStorage
      var injectedName = urlParams.get('playerName') || '';
      if(!injectedName){
        try{ injectedName = localStorage.getItem('co-v17-learnerName') || ''; }catch(_){}
      }
      // Pre-fill the name input so skipIntroBtn check passes
      if(injectedName){
        var ni = document.getElementById('learnerNameInput');
        if(ni) ni.value = injectedName;
        state.learnerName = injectedName;
        try{ localStorage.setItem('co-v17-learnerName', injectedName); }catch(_){}
      }
      var skipBtn = document.getElementById('skipIntroBtn');
      if(skipBtn && injectedName){ skipBtn.click(); }
      else if(injectedName){
        if(typeof revealSimulationChrome === 'function') revealSimulationChrome();
        if(typeof showScreen === 'function') showScreen('network');
        if(typeof render === 'function') render();
      }
      // If no name available yet, wait for SET_PLAYER postMessage to trigger skip
      // Belt-and-suspenders: always hide intro in autoStart mode
      const introHide = document.getElementById('screen-intro');
      if(introHide){ introHide.style.display='none'; introHide.classList.remove('active'); }
    }catch(_){}
  }
})();

